+// Used to verify that Bind does not try to allocate the whole body on the heap
+type endlessReader struct {
+	prefix []byte
+	read   int64
+}
+
+func (r *endlessReader) Read(p []byte) (int, error) {
+	if len(r.prefix) > 0 {
+		n := copy(p, r.prefix)
+		r.prefix = r.prefix[n:]
+		r.read += int64(n)
+		return n, nil
+	}
+	for i := range p {
+		p[i] = 'A'
+	}
+	r.read += int64(len(p))
+	return len(p), nil
