+	if err == nil {
+		t.Fatal("expected Bind to reject oversized body, got nil error")
+	}
+
+	if body.read > MaxBindBodyBytes+(1<<20) {
+		t.Fatalf("Bind read %d bytes, want at most ~%d", body.read, MaxBindBodyBytes)
+	}
